/**
 * Milestone M4 Expansion — Part 1 (90 Curated Academic TOEIC X-Ray Items)
 * Topics:
 *   1. RC_P7_DETAIL_MAIN     (+45 items: EXP2026_RC_P7_DET_Q001..Q045) -> 0 + 45 = 45
 *   2. RC_P7_INFERENCE_CROSS (+45 items: EXP2026_RC_P7_INF_Q001..Q045) -> 0 + 45 = 45
 */

import { buildQuestionFromSpec } from "./m2_items_part1.mjs";

const KEYS = ["A", "B", "C", "D"];

function makeM4Generator({
  topicId,
  topicNameVi,
  idPrefix,
  part = 7,
  skillCategory = "READING_COMPREHENSION",
  defaultBand = 650,
  defaultTime = 45,
  commonTrapVi,
  errCode = "ERR_COMPREHENSION_TRAP",
  errNameVi = "Bẫy từ khóa xuất hiện y hệt trong bài nhưng sai chi tiết (Verbatim Keyword Trap)",
  scenarios,
}) {
  return function generate() {
    // Precompute IDs so each item can link to 2 valid twin questions in the same topic
    const allIds = scenarios.map((_, idx) => `${idPrefix}_Q${String(idx + 1).padStart(3, "0")}`);

    return scenarios.map((sc, idx) => {
      const qNum = idx + 1;
      const id = allIds[idx];
      const diff = idx < 15 ? 1 : idx < 30 ? 2 : 3;
      const band = sc.band || (diff === 1 ? 500 : diff === 2 ? 650 : 800);

      const correctIdx = idx % 4;
      const correctKey = KEYS[correctIdx];
      const options = {};
      let dPtr = 0;

      for (let kIdx = 0; kIdx < 4; kIdx++) {
        const k = KEYS[kIdx];
        if (kIdx === correctIdx) {
          options[k] = {
            text: sc.corr,
            role: sc.role,
            errCode: null,
            errNameVi: null,
            whyWrongVi: "",
          };
        } else {
          const dItem = sc.dist[dPtr++];
          const dText = typeof dItem === "object" ? dItem.t : dItem;
          const dRole = typeof dItem === "object" ? dItem.r : "Comprehension Distractor (Verbatim / Opposite Trap)";
          const dWhy =
            typeof dItem === "object" && dItem.w
              ? dItem.w
              : `Sai thông tin so với bằng chứng trong đoạn trích: "${dText}" mâu thuẫn với dữ kiện "${sc.la} ... ${sc.ra}" (${sc.rule}).`;
          options[k] = {
            text: dText,
            role: dRole,
            errCode: sc.errCode || errCode,
            errNameVi: sc.errNameVi || errNameVi,
            whyWrongVi: dWhy,
          };
        }
      }

      const twin1 = allIds[(idx + 1) % allIds.length];
      const twin2 = allIds[(idx + 2) % allIds.length];

      return buildQuestionFromSpec({
        id,
        number: 147 + (idx % 54),
        part,
        topicId,
        topicNameVi,
        skillCategory,
        difficultyLevel: diff,
        targetBand: band,
        recommendedTime: defaultTime,
        microFormulaVi: sc.rule,
        commonTrapVi: sc.trap || commonTrapVi,
        leftContext: sc.l,
        rightContext: sc.r,
        leftAnchor: sc.la,
        rightAnchor: sc.ra,
        requiredRole: sc.role,
        options,
        correctKey,
        explanationVi: `Chốt chặn đọc hiểu & Paraphrase: Dữ kiện gốc "${sc.la} ... ${sc.ra}" tương đương học thuật với (${correctKey}) "${sc.corr}" theo quy tắc "${sc.rule}".`,
        vocab: [{ word: sc.v[0], pos: sc.v[1], meaning_vi: sc.v[2] }],
        collocation: sc.c,
        similarIds: [twin1, twin2],
      });
    });
  };
}

